data.query:
query WorkOrderProcessDistribution($where:WorkOrderProcessDistributionWhereInput!) {
  workOrderProcessDistribution(where:$where) {
    edges {
      node {
        balanceQuantity
        producedQuantity
        scrappedQuantity
        requiredQuantity
  }
  }
}
}

data.mutation:
mutation UpdateOutput($distributionUpdate: [WorkOrderProcessDistributionUpdatePayloadInput!]!, $outputUpdate: [ProductionSetupOutputUpdatePayloadInput!]!) {
  updateWorkOrderProcessDistribution(payload:$distributionUpdate) { id balanceQuantity }
  updateProductionSetupOutput(payload: $outputUpdate) { id workcenterId}
}

